<script>
(function () {
  "use strict";

  var form = document.getElementById("booking");
  var partyInput = document.getElementById("party");
  var DEPOSIT_PER_GUEST = 10;

  // --- MCP host bridge (best-effort; no-op if unavailable) ------------------
  function notifyHost(type, data) {
    try {
      window.parent.postMessage({ source: "mcp-app", type: type, data: data }, "*");
    } catch (e) { /* sandboxed / no parent */ }
  }

  // --- Party stepper --------------------------------------------------------
  function clampParty() {
    var v = parseInt(partyInput.value, 10);
    if (isNaN(v)) v = 1;
    v = Math.max(1, Math.min(12, v));
    partyInput.value = v;
    return v;
  }
  document.getElementById("minus").addEventListener("click", function () {
    partyInput.value = clampParty() - 1; clampParty(); updateSummary();
  });
  document.getElementById("plus").addEventListener("click", function () {
    partyInput.value = clampParty() + 1; clampParty(); updateSummary();
  });
  partyInput.addEventListener("input", updateSummary);

  // --- Summary --------------------------------------------------------------
  function fmtMoney(n) { return "$" + n.toFixed(2); }

  function updateSummary() {
    var guests = clampParty();
    var date = document.getElementById("date").value;
    var time = document.getElementById("time").value;
    document.getElementById("s-guests").textContent = guests;
    document.getElementById("s-total").textContent = fmtMoney(guests * DEPOSIT_PER_GUEST);

    var when = "—";
    if (date && time) {
      var d = new Date(date + "T00:00:00");
      when = d.toLocaleDateString(undefined, { month: "short", day: "numeric" }) + " · " + time;
    }
    document.getElementById("s-when").textContent = when;
  }
  document.getElementById("date").addEventListener("change", updateSummary);
  document.getElementById("time").addEventListener("change", updateSummary);

  // Default date = tomorrow, min = today
  (function initDate() {
    var el = document.getElementById("date");
    var t = new Date();
    var min = t.toISOString().slice(0, 10);
    el.min = min;
    var tomorrow = new Date(t.getTime() + 86400000);
    el.value = tomorrow.toISOString().slice(0, 10);
  })();

  // --- Validation -----------------------------------------------------------
  function fieldOf(input) { return input.closest(".field"); }

  function validate(input) {
    var ok = true;
    if (input.type === "email") {
      ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value.trim());
    } else if (input.hasAttribute("required")) {
      ok = input.value.trim() !== "";
    }
    fieldOf(input).classList.toggle("invalid", !ok);
    return ok;
  }

  ["name", "email", "date", "time"].forEach(function (id) {
    var el = document.getElementById(id);
    el.addEventListener("blur", function () { validate(el); });
    el.addEventListener("input", function () {
      if (fieldOf(el).classList.contains("invalid")) validate(el);
    });
  });

  // --- Submit ---------------------------------------------------------------
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var required = ["name", "email", "date", "time"].map(function (id) {
      return document.getElementById(id);
    });
    var allOk = required.map(validate).every(Boolean);
    if (!allOk) {
      var firstBad = form.querySelector(".field.invalid input, .field.invalid select");
      if (firstBad) firstBad.focus();
      return;
    }

    var guests = clampParty();
    var payload = {
      name: document.getElementById("name").value.trim(),
      email: document.getElementById("email").value.trim(),
      date: document.getElementById("date").value,
      time: document.getElementById("time").value,
      party: guests,
      notes: document.getElementById("notes").value.trim(),
      deposit: guests * DEPOSIT_PER_GUEST,
      venue: document.getElementById("venue").textContent
    };

    var btn = document.getElementById("submit");
    btn.disabled = true;
    btn.textContent = "Confirming…";

    notifyHost("tool.submit", payload);

    // Optimistic local confirmation for standalone rendering.
    var ref = "BK-" + Math.random().toString(36).slice(2, 8).toUpperCase();
    setTimeout(function () {
      form.classList.add("hidden");
      var done = document.getElementById("done");
      done.classList.remove("hidden");
      document.getElementById("done-detail").textContent =
        payload.party + " guest" + (payload.party > 1 ? "s" : "") +
        " · " + document.getElementById("s-when").textContent;
      document.getElementById("done-ref").textContent = "Ref " + ref;
      notifyHost("tool.result", Object.assign({ reference: ref }, payload));
    }, 500);
  });

  updateSummary();
  notifyHost("app.ready", {});
})();
</script>
